%[text] 
% Discretize the domain, N-1 = # cells, N = # boundaries
N = 101;                 % Number of "faces"
L = 1;                  % Length of the domain
dx = L/(N-1);           % Size of the cells
xf = 0:dx:L;            % Location of the faces
xc = dx/2:dx:L;         % Location of the cell centers
%%
% Initial conditions -- put the initial density here
rho = 0.8*ones(1,N-1);  % Set the density to 0.8 in the first half of the domain
rho(round(N/2):end) = 0.2;
sum(rho)*dx %[output:3e925791]
figure %[output:81b8731e]
pt = plot(xc,rho); %[output:81b8731e]
t = title(sprintf("t = %d s",0)); %[output:81b8731e]
xline(0.75) %[output:81b8731e]
ylim([0 1]) %[output:81b8731e]

%%
% Define some things about time/dt
dt = dx;              % Change this up to see how it behaves!
tfinal = 5;             % Run the simulation for 2 seconds

% Define the boundary condition values
FLBC = (0.8 - 0.8^2);   % Define the left and right fluxes
FRBC = (0.2 - 0.2^2);   % Define the left and right fluxes

% Loop in time -- to perform FVM at each step
for time = 0:dt:tfinal %[output:group:928e74c8]

    % Calculate the cell-interface fluxes
    flux(1) = FLBC;     % Start with the boundary cells
    flux(N) = FRBC;

    % Next loop over each of the "internal" cells to determine the flux on
    % the "west" side of the cell (note the west flux flux(i) of cell(i) 
    % is the east flux of cell (i-1)
    for(i = 2:N-1)
        FluxL = rho(i-1) - rho(i-1)^2;  % Flux assuming left (i-1) cell's density is used
        FluxR = rho(i) - rho(i)^2;      % Flux assuming right (i)  cell's density is used

        % Perform the Godunov flux evaluation at the face -- see notes for
        % details
        if(rho(i-1) <= rho(i))
            flux(i) = min([FluxL, FluxR]);
        else
            flux(i) = max([FluxL, FluxR]);
            if(rho(i-1)>0.5 && rho(i)<0.5)
                 flux(i) = 0.25;     % This is when we need the max flux and the points are on either side of the max!
            end
        end
    end
     
    % We can add a traffic light here! Turn on traffic light every half
    % second
    % if(mod(time,1) > 0.5)
        % flux(round(ceil(3*end/4))) = 0;
    % end


    % Finite volume method control volume evaluation for each cell
    % Update the density based on the FVM conservation law/equation used
    for(i = 1:N-1)
        rho_new(i) = rho(i) - dt/dx*(flux(i+1) - flux(i));
    end

    rho_new(1) = 0.8;
    rho_new(end) = 0.2;
    rho = rho_new;

    % Plot the result
    pt.YData = rho; %[output:7392ae46]
    t.String = sprintf("t = %d s",time);
    drawnow
end %[output:group:928e74c8]

